def request_token(client_id, secret):
  payload = {
    "client_id": client_id,
    "client_secret": secret,
    "grant_type": "client_credentials",
  }
  response = session.post(TOKEN_URL, json=payload, timeout=5)
  response.raise_for_status()
  return response.json()["access_token"]
